import { validateEmail as emailUtilValidateEmail } from './email-util';
import { translate } from '@ps-refarch-ux/mfe-utils';
export function validateMaxTextLength(input, maxLength, context) {
    const result = {
        isValid: input.length <= maxLength
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The text must have xx or less characters.', { maxLength: maxLength });
    }
    return result;
}
export function validateMinTextLength(input, minLength, context) {
    const result = {
        isValid: input.length >= minLength
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The text must have xx or more characters.', { minLength: minLength });
    }
    return result;
}
export function validateExcludeChars(input, condition, context) {
    //console.log('validating excludeChars');
    const result = {
        isValid: !condition.pattern.test(input)
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|Must not contain any characters in xx', { excludeChars: condition.excludeChars });
    }
    //console.log('result: ' + result.isValid);
    return result;
}
export function validateRegex(input, condition, context) {
    const result = {
        //!== is like doing an XOR on the test and inverse
        isValid: condition.pattern.test(input) !== condition.inverse
    };
    if (!result.isValid) {
        result.errorMessage = condition.errorMessage;
    }
    return result;
}
export function validateEmail(input, condition, context) {
    const result = {
        isValid: emailUtilValidateEmail(input)
    };
    if (!result.isValid) {
        result.errorMessage = translate('neon|validation engine|The email is not in the correct format.');
    }
    return result;
}
